mapper.select:
SELECT * , CAST(COUNT(*) OVER() AS INTEGER) AS totcnt , TO_CHAR(UPDT_TIME_STEMP,'YYYY-MM-DD HH24:MI:SS') AS UPDT_DT , TO_CHAR(MIN(UPDT_TIME_STEMP) OVER(), 'YYYY-MM-DD HH24:MI:SS') AS START_UPDT_DT , TO_CHAR(MAX(UPDT_TIME_STEMP) OVER(),'YYYY-MM-DD HH24:MI:SS') AS END_UPDT_DT FROM ${saveTbNm} WHERE 1=1
AND ${fieldName} LIKE '%' || #{dataValue} || '%'
ORDER BY UPDT_TIME_STEMP DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}
